        }
      },
      "schedule": {
        "entityId": {
          "type": "string",
          "description": "用于打开日程详情的示例事件 ID",
          "sampleValue": "focus-demo-calendar-event"
        },
        "timeText": {
          "type": "string",
          "description": "静态示例日程时间",
          "sampleValue": "21:30"
        },
        "title": {
          "type": "string",
          "description": "静态示例日程标题",
          "sampleValue": "睡前整理"
        },
        "summary": {
          "type": "string",
          "description": "静态示例日程内容摘要",
          "sampleValue": "回顾今天并准备明日清单"
        },
        "cta": {
          "type": "string",
          "description": "查看日程详情的短动作文本",
          "sampleValue": "查看"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_focus.png",
      "description": "专注模式彩色图标，适合用于夜间专注卡片的场景识别和视觉锚点。"
    },
    {
      "src": "resources/base/media/icon_schedule.png",
      "description": "日程彩色图标，适合用于示例日程事件或查看日程详情入口。"
    }
  ]
}

